import { Component, OnInit } from "@angular/core";
import { FormBuilder, FormGroup, Validators, FormArray } from "@angular/forms";
import { FaIconLibrary } from "@fortawesome/angular-fontawesome";
import { fas } from "@fortawesome/free-solid-svg-icons";
import { mockedAuthorsList } from "../../../shared/mocks/mocks"; // Adjust path as needed

@Component({
  selector: "app-course-form",
  templateUrl: "./course-form.component.html",
  styleUrls: ["./course-form.component.scss"],
})
export class CourseFormComponent implements OnInit {
  constructor(public fb: FormBuilder, public library: FaIconLibrary) {
    library.addIconPacks(fas);
    this.totalAuthors = [...mockedAuthorsList]; // Clone to avoid mutating original
  }

  courseForm!: FormGroup;
  totalAuthors: { id: number; name: string }[]; // All authors from mock
  courseAuthors: { id: number; name: string }[] = []; // Not used anymore, replaced by FormArray

  ngOnInit() {
    this.createCourseForm();
  }

  createCourseForm() {
    this.courseForm = this.fb.group({
      title: ["", [Validators.required, Validators.minLength(2)]],
      description: ["", [Validators.required, Validators.minLength(2)]],
      authors: this.fb.array([]), // FormArray for course authors
      newAuthor: this.fb.group({
        name: [
          "",
          [Validators.minLength(2), Validators.pattern("^[a-zA-Z0-9 ]+$")],
        ],
      }),
      duration: [null, [Validators.required, Validators.min(0)]],
    });
  }

  get authors(): FormArray {
    return this.courseForm.get("authors") as FormArray;
  }

  get availableAuthors() {
    const selectedIds = this.authors.controls.map(
      (control) => control.value.id
    );
    return this.totalAuthors.filter(
      (author) => !selectedIds.includes(author.id)
    );
  }

  addAuthorToCourse(author: { id: number; name: string }) {
    this.authors.push(
      this.fb.group({
        id: [author.id],
        name: [author.name],
      })
    );
  }

  removeAuthorFromCourse(index: number) {
    this.authors.removeAt(index);
  }

  createAuthor() {
    const newAuthorName = this.courseForm.get("newAuthor.name")?.value?.trim();
    if (newAuthorName && this.courseForm.get("newAuthor")?.valid) {
      const newAuthor = {
        id: Date.now(),
        name: newAuthorName,
      };
      this.totalAuthors.push(newAuthor);
      this.courseForm.get("newAuthor")?.reset();
    }
  }

  onSubmit() {
    if (this.courseForm.valid) {
      const formValue = {
        ...this.courseForm.value,
      };
      console.log("Course form submitted:", formValue);
    } else {
      this.courseForm.markAllAsTouched();
    }
  }
}
<h2>Course Edit/Create Page</h2>

<form [formGroup]="courseForm" (ngSubmit)="onSubmit()">
  <div class="app-plate">
    <div class="course">
      <h3>Main Info</h3>

      <!-- Title -->
      <div class="form__control">
        <label for="title">Title</label>
        <input
          type="text"
          id="title"
          formControlName="title"
          placeholder="Input title"
        />
        <!-- Error messages for title -->
      </div>

      <!-- Description -->
      <div class="form__control">
        <label for="description">Description</label>
        <textarea
          id="description"
          formControlName="description"
          placeholder="Input description"
          rows="4"
        ></textarea>
        <!-- Error messages for description -->
      </div>

      <div class="separator"></div>
      <h3>Authors</h3>

      <!-- New Author -->
      <div class="form__control" formGroupName="newAuthor">
        <label for="author">New Author</label>
        <input
          type="text"
          id="author"
          formControlName="name"
          placeholder="Input author name"
        />
        <app-button
          type="button"
          (click)="createAuthor()"
          buttonText="Create Author"
        ></app-button>
        <!-- Error messages for new author -->
      </div>

      <!-- Available Authors -->
      <div class="course__authors">
        <h4>Available Authors</h4>
        <ul>
          <li *ngFor="let author of availableAuthors">
            {{ author.name }}
            <app-button
              type="button"
              (click)="addAuthorToCourse(author)"
              buttonText="Add"
            ></app-button>
          </li>
        </ul>
      </div>

      <!-- Course Authors -->
      <div class="course__authors">
        <h4>Course Authors</h4>
        <ul>
          <li *ngFor="let authorCtrl of authors.controls; let i = index">
            {{ authorCtrl.value.name }}
            <app-button
              type="button"
              (click)="removeAuthorFromCourse(i)"
              buttonText="Delete"
            ></app-button>
          </li>
        </ul>
      </div>

      <!-- Duration -->
      <div class="separator"></div>
      <h3>Duration</h3>
      <div class="form__control">
        <label for="duration">Duration (minutes)</label>
        <input
          type="number"
          id="duration"
          formControlName="duration"
          placeholder="Input duration"
        />
        <!-- Error messages for duration -->
      </div>

      <!-- Submit Button -->
      <div class="form__action">
        <app-button type="submit" buttonText="Submit"></app-button>
      </div>
    </div>
  </div>
</form>
